import{_ as s,o as l,c as a,a2 as r}from"./chunks/framework.DxR7mb1F.js";const i="/bluebook/help/workbuddy-scenario-survey.png",_=JSON.parse('{"title":"帮你解决 WorkBuddy 使用场景问题","titleTemplate":false,"description":"如果你不知道如何用 WorkBuddy 解决真实工作问题，可以提交场景问卷。我们会评估需求、联系沟通，并将具有复用价值的解决方案制作成开源 Case。","frontmatter":{"title":"帮你解决 WorkBuddy 使用场景问题","titleTemplate":false,"description":"如果你不知道如何用 WorkBuddy 解决真实工作问题，可以提交场景问卷。我们会评估需求、联系沟通，并将具有复用价值的解决方案制作成开源 Case。","breadcrumbTitle":"帮你解决","aside":false,"outline":false,"pageClass":"help-you-page"},"headers":[],"relativePath":"help/index.md","filePath":"help/index.md","lastUpdated":1786808975000}'),t={name:"help/index.md"};function p(d,e,o,n,c,h){return l(),a("div",null,[...e[0]||(e[0]=[r('<div class="help-hero"><div class="help-hero__copy"><p class="help-pixel-label">SCENARIO SUPPORT · OPEN CASES</p><h1>有工作场景，不知道怎么用 WorkBuddy 解决？</h1><p class="help-hero__lead">把你的真实问题告诉我们。我们会阅读每一份场景问卷，评估 WorkBuddy 是否能够解决；如果需要补充信息，我们会联系你进一步沟通。</p><p>具有代表性和复用价值的问题，我们会尝试做成完整 Case，写清使用的 Skill、操作过程、任务描述和最终效果，并开源到社区案例集，帮助更多遇到同类问题的人。</p><div class="help-hero__actions"><a class="help-button help-button--primary" href="#scenario-survey">扫码填写问卷</a><a class="help-button" href="/cases/">查看开源 Case</a></div></div><div id="scenario-survey" class="help-survey-card"><div class="help-survey-card__heading"><span>01</span><div><strong>WorkBuddy 场景收集调查问卷</strong><small>扫码后填写你的真实需求</small></div></div><a href="/help/workbuddy-scenario-survey.png" target="_blank" rel="noreferrer" aria-label="查看 WorkBuddy 场景收集调查问卷二维码大图"><img src="'+i+'" alt="WorkBuddy 场景收集调查问卷二维码" loading="eager"></a><p>使用手机扫码填写；如果你正在手机上阅读，可以点击图片查看大图后长按识别。</p></div></div><section class="help-process" aria-labelledby="help-process-title"><p class="help-pixel-label">HOW IT WORKS</p><h2 id="help-process-title">提交之后，我们会怎么做</h2><div class="help-process__grid"><article><span>01</span><h3>理解你的场景</h3><p>了解你现在怎样工作、卡在哪里、已有输入以及希望得到什么结果。</p></article><article><span>02</span><h3>评估解决路径</h3><p>判断 WorkBuddy 是否适合处理，并梳理可能需要的 Skill、权限和交付方式。</p></article><article><span>03</span><h3>联系与验证</h3><p>如果场景需要更多信息，我们会通过问卷中留下的联系方式与你确认，并验证方案。</p></article><article><span>04</span><h3>制作开源 Case</h3><p>具有通用价值的解决方案会被整理成可复现 Case，审核后公开到社区案例集。</p></article></div></section><section class="help-submit-guide" aria-labelledby="help-submit-title"><div><p class="help-pixel-label">WHAT TO PREPARE</p><h2 id="help-submit-title">怎样描述问题，更容易得到帮助</h2></div><ul><li><strong>真实场景：</strong>你在什么岗位或任务中遇到了问题。</li><li><strong>当前做法：</strong>现在需要哪些步骤，大概花多少时间。</li><li><strong>输入资料：</strong>通常会用到哪些文件、网页、系统或数据。</li><li><strong>期望结果：</strong>希望 WorkBuddy 最终交付什么，以及怎样算完成。</li><li><strong>安全边界：</strong>是否涉及账号权限、敏感数据、文件修改或对外发布。</li></ul></section><div class="help-note"><strong>关于隐私与联系</strong><p>请不要在问卷中提交密码、密钥、客户隐私或不方便公开的内部资料。我们只会在需要补充信息或可以推进解决方案时，通过你主动留下的联系方式与你沟通。</p></div>',4)])])}const g=s(t,[["render",p]]);export{_ as __pageData,g as default};
